#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

long long power_mod(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    long long p, k;
    cin >> p >> k;
    const long long pcon = 1000000007;
    vector<long long> inv_table(1000003, 0);
    inv_table[1] = 1;
    for (long long i = 2; i < 1000003; ++i) {
        long long a = pcon / i;
        long long b = pcon % i;
        long long c = (a * (pcon - inv_table[b])) % pcon;
        inv_table[i] = c;
    }
    long long total_ans = 0;
    if (k == 0) {
        total_ans = 1;
        for (long long i = 0; i < p - 1; ++i) {
            total_ans = (total_ans * p) % pcon;
        }
    } else {
        long long prod = 1, first_found_flag = 0, idx_jj = 0;
        for (long long i = 1; i < p; ++i) {
            prod = (prod * k) % p;
            if ((prod % p) == 1 && first_found_flag == 0) {
                idx_jj = i;
                first_found_flag = 1;
            }
        }
        total_ans = 1;
        long long t = (p - 1) / idx_jj;
        if (k == 1) {
            total_ans = 1;
            for (long long i = 0; i < p; ++i) {
                total_ans = (total_ans * p) % pcon;
            }
        } else {
            long long sum_res = 0;
            for (long long i = 1; i <= t; ++i) {
                long long temp = (inv_table[i] * (t - i + 1)) % pcon;
                temp = (temp * t) % pcon;
                temp = (temp * idx_jj) % pcon;
                sum_res = (sum_res + temp) % pcon;
            }
            total_ans = (total_ans + sum_res) % pcon;
        }
    }
    cout << total_ans;
}
